package com.asterion.foundry;
import android.app.*;import android.content.*;import android.os.*;import android.graphics.*;import org.json.*;import java.io.*;import java.nio.file.*;import java.util.concurrent.*;
/** One bounded worker. Each stage is published atomically; stale running jobs require explicit resume. */
public final class ProductionService extends Service {
 static volatile boolean active=false;private Store store;private ExecutorService worker;private volatile boolean stop=false;private String current;
 public void onCreate(){super.onCreate();store=new Store(this);store.recover();worker=Executors.newSingleThreadExecutor();NotificationManager nm=getSystemService(NotificationManager.class);nm.createNotificationChannel(new NotificationChannel("production","Asset production",NotificationManager.IMPORTANCE_LOW));}
 public int onStartCommand(Intent in,int flags,int sid){
  if(in==null){stopSelf();return START_NOT_STICKY;}if("pause".equals(in.getAction())){stop=true;return START_NOT_STICKY;}
  if(active)return START_NOT_STICKY;active=true;stop=false;
  Notification n=new Notification.Builder(this,"production").setSmallIcon(android.R.drawable.stat_sys_upload).setContentTitle("Asterion Foundry").setContentText("Processing locally · checkpoints enabled").setOngoing(true).setContentIntent(PendingIntent.getActivity(this,0,new Intent(this,MainActivity.class),PendingIntent.FLAG_IMMUTABLE)).build();startForeground(7,n);
  worker.submit(()->{PowerManager.WakeLock lock=getSystemService(PowerManager.class).newWakeLock(PowerManager.PARTIAL_WAKE_LOCK,"Foundry:production");lock.acquire(2*60*60*1000L);try{for(JSONObject job:store.jobs())if("queued".equals(job.getString("state"))){current=job.getString("id");try{run(job);}catch(Paused p){store.state(current,"paused",store.job(current).getInt("stage"),p.getMessage());break;}catch(Exception e){store.state(current,"failed",store.job(current).getInt("stage"),e.getClass().getSimpleName()+": "+e.getMessage());}if(stop)break;}}catch(Exception e){android.util.Log.e("Foundry","queue",e);}finally{if(lock.isHeld())lock.release();active=false;stopForeground(STOP_FOREGROUND_REMOVE);stopSelf();}});return START_NOT_STICKY;
 }
 static class Paused extends Exception{Paused(String m){super(m);}}
 void check()throws Paused{if(stop)throw new Paused("Paused at durable checkpoint");PowerManager pm=getSystemService(PowerManager.class);if(pm.getCurrentThermalStatus()>=PowerManager.THERMAL_STATUS_SEVERE)throw new Paused("Paused to cool the phone; resume when ready");ActivityManager.MemoryInfo m=new ActivityManager.MemoryInfo();getSystemService(ActivityManager.class).getMemoryInfo(m);if(m.lowMemory||m.availMem<350L*1024*1024)throw new Paused("Paused for low available memory");if(store.root.getUsableSpace()<256L*1024*1024)throw new Paused("Paused for low storage");}
 void stage(String id,int n,String msg)throws Exception{check();store.state(id,"running",n,msg);}
 void run(JSONObject job)throws Exception{
  String id=job.getString("id");JSONObject req=new JSONObject(job.getString("request"));File project=store.project(id);long begin=SystemClock.elapsedRealtime();boolean reused=false;
  String kind=req.getString("kind"),source=req.optString("source"),sourceHash=source.isEmpty()?"":FilesUtil.hash(new File(source));String key=FilesUtil.hash(Recipes.VERSION+"|"+kind+"|"+req.getDouble("scale")+"|"+req.getInt("detail")+"|"+sourceHash);
  FilesUtil.write(new File(project,"project.json"),req.toString(2));File cached=new File(store.root,"cache/"+key+".mesh"),checkpoint=new File(project,"checkpoint.mesh");Mesh mesh;
  stage(id,0,"Preparing geometry");
  if(checkpoint.isFile()){mesh=Mesh.load(checkpoint);reused=true;}else if(cached.isFile()){try{mesh=Mesh.load(cached);reused=true;}catch(Exception corrupt){mesh=generate(req);}}else mesh=generate(req);
  mesh.save(checkpoint);stage(id,1,"Geometry saved · checking mesh");String validation=mesh.validate();if(!cached.exists())mesh.save(cached);
  if(req.optBoolean("pauseAfterGeometry",false)&&!job.optString("message").equals("Resume requested")){throw new Paused("Acceptance checkpoint saved. Resume to finish export.");}
  stage(id,2,"Writing editable asset and GLB");File glb=new File(project,"asset.glb");Glb.write(mesh,glb);
  stage(id,3,"Writing provenance and validation receipt");JSONObject receipt=new JSONObject(validation);receipt.put("schema","asterion.foundry.receipt.v1");receipt.put("job",id);receipt.put("recipe",kind);receipt.put("recipe_version",Recipes.VERSION);receipt.put("asset_sha256",FilesUtil.hash(glb));receipt.put("source_sha256",sourceHash);receipt.put("cache_key",key);receipt.put("reused",reused);receipt.put("duration_ms",SystemClock.elapsedRealtime()-begin);receipt.put("backend","Android CPU / ART");receipt.put("vulkan_compute","not_implemented");receipt.put("qnn","not_implemented");receipt.put("unreal_import_executed",false);receipt.put("noworld_binding","unbound; exact canonical manifest required");receipt.put("visual_quality","UNVALIDATED");receipt.put("production_method",kind.equals("Image silhouette")?"deterministic_2_5d_extrusion":kind.equals("OBJ geometry")?"triangulated_OBJ_geometry_only":"parametric_template");receipt.put("source_appearance_preserved",false);receipt.put("mobile_optimization","not_validated");receipt.put("rig_validation",mesh.bones.isEmpty()?"not_applicable":"hierarchy_and_normalized_rigid_weights_only");
  FilesUtil.write(new File(project,"receipt.json"),receipt.toString(2));FilesUtil.write(new File(project,"import-manifest.json"),new JSONObject().put("schema","asterion.foundry.intermediate.v1").put("format","glTF2 GLB").put("units","metres").put("up_axis","Y").put("handedness","right").put("asset","asset.glb").put("sha256",FilesUtil.hash(glb)).put("identity_id",JSONObject.NULL).put("version_id",JSONObject.NULL).put("manifestation_id",JSONObject.NULL).put("native_acceptance",false).put("warnings",new JSONArray().put("NoWorld adapter has not admitted this asset").put("Do not replace exact skeletons, rest poses, morphs or facial alpha materials with this template")).toString(2));
  store.record(id,kind,SystemClock.elapsedRealtime()-begin,reused,receipt);store.state(id,"complete",4,"Export ready · visual quality unvalidated"+(reused?" · reused geometry":""));
 }
 Mesh generate(JSONObject q)throws Exception{String kind=q.getString("kind");if(kind.equals("Image silhouette")){BitmapFactory.Options opt=new BitmapFactory.Options();opt.inJustDecodeBounds=true;BitmapFactory.decodeFile(q.getString("source"),opt);if(opt.outWidth<1||opt.outHeight<1)throw new IOException("Unreadable image");opt.inSampleSize=Math.max(1,Math.max(opt.outWidth,opt.outHeight)/160);opt.inJustDecodeBounds=false;Bitmap b=BitmapFactory.decodeFile(q.getString("source"),opt);if(b==null)throw new IOException("Image decoding failed");float ratio=96f/Math.max(b.getWidth(),b.getHeight());Bitmap small=Bitmap.createScaledBitmap(b,Math.max(1,(int)(b.getWidth()*ratio)),Math.max(1,(int)(b.getHeight()*ratio)),false);int[] pix=new int[small.getWidth()*small.getHeight()];small.getPixels(pix,0,small.getWidth(),0,0,small.getWidth(),small.getHeight());Mesh mesh=Recipes.silhouette(pix,small.getWidth(),small.getHeight(),(float)q.getDouble("scale"),(float)q.getDouble("scale")*.08f);if(small!=b)small.recycle();b.recycle();return mesh;}if(kind.equals("OBJ geometry"))return Glb.readObj(new File(q.getString("source")));return Recipes.create(kind,(float)q.getDouble("scale"),q.getInt("detail"));}
 @Override public void onTimeout(int id,int type){stop=true;if(current!=null)try{store.state(current,"paused",store.job(current).getInt("stage"),"Android service time limit; resume from saved checkpoint");}catch(Exception ignored){}stopForeground(STOP_FOREGROUND_REMOVE);stopSelf();}
 public IBinder onBind(Intent i){return null;}
 public void onDestroy(){stop=true;worker.shutdown();super.onDestroy();}
}
